<script setup>
import {computed,reactive,ref} from 'vue'
import {useCreation} from '@/ports/creation'
import Icon from './CreationIcon.vue'
import ProductScene from './ProductScene.vue'
const p=useCreation(),s=p.state,d=s.modalData||{},kind=s.modal
const form=reactive({name:d.name||'',type:d.type||'提示词',text:d.text||'',category:'风格',tags:[],scene:d.scene||'amber'})
const text=ref(d.node?.text||''),input=ref(''),referenceSource=ref('个人资产'),applyNode=ref(''),feedback=reactive({version:'脚本初稿',status:'待确认',opinion:''}),saved=ref(false),onlyAvailable=ref(false)
const keys=['number','duration','scale','camera','visual','sound','emotion','environment','imagePrompt','motionPrompt']
const outputRows=computed(()=>s.rows.filter(r=>!s.selectedRows.length||s.selectedRows.includes(r.id)))
const outputs=computed(()=>s.nodes.filter(n=>n.type!=='脚本'&&n.status==='success'&&(!s.selectedRows.length||s.selectedRows.includes(n.rowId))))
const title=computed(()=>({'save':'保存为资产','reference':'引用内容','apply':'引用到画布','script-input':'生成分镜脚本','script-editor':'编辑分镜脚本','text-editor':'文本详情','download':'下载镜头素材','rename-project':'重命名项目','rename-session':'重命名会话','delete-session':'删除会话？','asset-detail':'资产详情','row-reference':'分镜行参考','optimize':'优化提示词','tasks':'生成任务','feedback':'确认与反馈','question':'选择视觉风格','projects':'我的项目','new-project':'新建空白项目','guide':'从灵感到素材','media-preview':'视频预览','export':d.kind==='excel'?'导出分镜 Excel':'导出为PDF格式','confirm':d.title}[kind]||'创作面板'))
function toggleTag(t){form.tags.includes(t)?form.tags.splice(form.tags.indexOf(t),1):form.tags.push(t)}
function reference(a){if(d.for==='node'){p.applyAsset(a,d.node.id);return}s.references.push(a);if(d.for==='agent')s.agentText+=' @'+a.name;p.closeModal();p.notify('已引用 '+a.name)}
function saveText(){p.setNode(d.node.id,'text',text.value);p.closeModal();p.notify('正文已保存')}
function close(){if(kind==='text-editor'&&text.value!==(d.node?.text||'')&&!window.confirm('正文尚未保存，确定放弃修改？'))return;p.closeModal()}
function printPreview(){p.notify('已打开正文导出预览；正式PDF排版待实现')}
</script>
<template><div class="modal-backdrop" @click.self="close()" @keydown.esc="close()"><section class="modal" role="dialog" aria-modal="true" :aria-label="title" :class="{'wide-modal':['script-editor','export'].includes(kind),'save-modal':kind==='save'}"><header class="modal-header"><div><span class="modal-kicker" v-if="kind==='save'">PERSONAL LIBRARY</span><h2>{{title}}</h2></div><div class="modal-header-actions"><button v-if="kind==='text-editor'" class="icon-button" title="导出" @click="saved=!saved"><Icon name="download"/></button><div v-if="kind==='text-editor'&&saved" class="export-menu"><button @click="printPreview()">导出为PDF格式</button></div><button class="icon-button" title="关闭" @click="close()"><Icon name="close" :size="22"/></button></div></header><div class="modal-content"><template v-if="kind==='save'"><div class="save-layout"><div class="save-preview"><div v-if="form.type==='提示词'" class="save-prompt"><span><Icon name="text" :size="15"/>提示词预览</span><textarea v-model="form.text" aria-label="提示词预览" placeholder="输入要保存的提示词"></textarea></div><ProductScene v-else :variant="form.scene"/><div class="preview-meta"><b>{{d.name||'当前提示词'}}</b><small>{{form.type}} · 来自当前项目</small></div></div><div class="save-fields"><label>资产名称 <em>*</em></label><div class="name-input"><input v-model="form.name" aria-label="资产名称" placeholder="为资产起一个容易找到的名字" maxlength="50"/><button class="ai-name" title="AI生成名称" @click="form.name=form.type==='提示词'?'自然晨光 · 商业摄影提示词':'琥珀香水 · 产品主视觉'"><Icon name="spark" :size="15"/></button></div><span class="field-hint">{{form.name.length}} / 50</span><label>保存位置 <em>*</em></label><select v-model="form.category" aria-label="保存位置"><option v-for="t in ['角色','场景','物品','风格','音效']" :key="t">{{t}}</option></select><label>设置标签 <span class="optional">可多选</span></label><div class="tag-picker"><button v-for="t in ['角色','场景','物品','风格','音效']" :key="t" :class="{selected:form.tags.includes(t)}" @click="toggleTag(t)"><Icon v-if="form.tags.includes(t)" name="check" :size="12"/>{{t}}</button></div><p class="help-copy">保存当前内容的独立版本，后续修改不会影响已保存的资产。</p><p v-if="s.error" class="field-error" role="alert">{{s.error}}</p></div></div></template><template v-else-if="kind==='reference'"><div class="filter-tabs reference-tabs"><button v-for="t in ['当前画布','其他项目','个人资产']" :key="t" :class="{active:referenceSource===t}" @click="referenceSource=t">{{t}}</button></div><p class="help-copy">仅显示你有权限访问的内容。引用不会自动生成。</p><div class="reference-list"><button v-for="a in referenceSource==='个人资产'?s.assets:[{id:'ref-product',name:referenceSource==='其他项目'?'品牌资料 · 产品参考':'产品主视觉 · 版本1',type:'图片',scene:'amber'}]" :key="a.id" @click="reference(a)"><div class="reference-thumb"><Icon v-if="a.type==='提示词'" name="text" :size="25"/><ProductScene v-else small/></div><div><b>{{a.name}}</b><span>{{a.type}} · {{referenceSource}}</span><p v-if="a.text">{{a.text}}</p></div><Icon name="plus" :size="18"/></button></div></template><template v-else-if="kind==='script-input'"><label>故事与创作要求</label><textarea v-model="s.prompt" rows="5" aria-label="脚本输入" placeholder="输入故事情节与风格；已有有效参考时，这里可以为空。"></textarea><div class="reference-pills"><span v-for="a in s.references" :key="a.id"><Icon name="attach" :size="12"/>{{a.name}}</span></div><button class="secondary-button" @click="p.openModal('reference',{for:'script'})"><Icon name="attach"/>引用内容</button><label class="upload-zone"><Icon name="upload" :size="25"/><b>上传文件或表格</b><span>文档与表格解析结果将在确认后应用</span><input type="file" accept=".pdf,.docx,.xlsx,.csv,.txt" @change="s.references.push({id:'file-'+Date.now(),name:$event.target.files[0]?.name||'文件',type:'文档'});p.notify('已选择文件，当前原型仅演示解析确认流程')"/></label><p class="help-copy">脚本节点只生成分镜表，图片与视频由连接的下游节点生成。</p><p v-if="s.error" class="field-error">{{s.error}}</p></template><template v-else-if="kind==='script-editor'"><div class="table-editor-scroll"><table class="script-table editable-table"><thead><tr><th v-for="c in s.columns" :key="c">{{c}}</th><th>操作</th></tr></thead><tbody><tr v-for="row in s.rows" :key="row.id"><td v-for="key in keys" :key="key"><textarea :value="row[key]" :aria-label="row.number+' '+key" :disabled="s.readonly" @input="p.editRow(row.id,key,$event.target.value)"></textarea></td><td><button class="icon-button" title="上移镜头" @click="p.moveRow(row.id,-1)">↑</button><button class="icon-button" title="下移镜头" @click="p.moveRow(row.id,1)">↓</button><button class="icon-button" title="删除镜头" @click="p.deleteRow(row.id)"><Icon name="trash" :size="16"/></button></td></tr></tbody></table></div><p class="help-copy">修改同步到画布，已有下游结果保留。排序和镜头号变化不改变行关联。</p><button class="secondary-button" @click="p.addRow()"><Icon name="plus"/>添加镜头</button></template><template v-else-if="kind==='text-editor'"><label>目标设定与风格</label><textarea v-model="text" rows="13" aria-label="文本正文" placeholder="请输入创作目标、受众、核心信息和期望风格…"></textarea><p class="help-copy">点击“确定”保存。导出不代替保存。</p></template><template v-else-if="kind==='download'"><div class="download-summary"><Icon name="download" :size="25"/><div><b>{{s.selectedRows.length||s.rows.length}} 个选定镜头</b><p>下载采用版本，文件名包含镜头号和素材名称。</p></div></div><div class="download-list"><div v-for="n in outputs" :key="n.id"><input type="checkbox" checked disabled :aria-label="'下载'+n.name"/><Icon :name="n.type==='视频'?'video':'image'"/><span>{{p.row(n.rowId)?.number||'独立素材'}}_{{n.name}}<small>版本1 · {{n.type}}</small></span><span class="ready-status">可下载</span></div><div v-for="row in outputRows.filter(r=>!outputs.some(n=>n.rowId===r.id))" :key="row.id" class="missing-download"><Icon name="clock"/><span>镜头 {{row.number}}<small>尚无已采用的生成结果</small></span><span>缺失</span></div></div><label class="checkbox-label"><input v-model="onlyAvailable" type="checkbox"/>仅下载当前可用素材，跳过缺失项</label><p class="help-copy">素材交付清单演示。真实文件打包、命名冲突及下载有效期在正式实现时接入。</p></template><template v-else-if="kind==='confirm'||kind==='delete-session'"><div class="confirmation-art"><Icon :name="kind==='delete-session'?'trash':'help'" :size="28"/></div><p class="confirm-description">{{kind==='delete-session'?'仅删除对话记录，画布节点、个人资产和已提交任务会保留。':d.description}}</p><p v-if="d.action==='generate'" class="help-copy">当前为交互预览，生成状态与结果使用模拟数据。</p></template><template v-else-if="['rename-project','rename-session','new-project'].includes(kind)"><label>{{kind==='rename-session'?'会话名称':'项目名称'}}</label><input v-model="input" autofocus :placeholder="kind==='rename-session'?s.activeSession:s.projectName"/></template><template v-else-if="kind==='apply'"><div class="asset-apply-preview"><Icon :name="d.type==='提示词'?'text':'image'"/><b>{{d.name}}</b><p>{{d.text||'引用当前媒体版本'}}</p></div><label>选择目标节点</label><select v-model="applyNode"><option disabled value="">请选择节点</option><option v-for="n in s.nodes.filter(n=>n.type!=='脚本')" :key="n.id" :value="n.id">{{n.name}}</option></select><p class="help-copy">提示词只应用文本，保留模型、参数和参考媒体。</p></template><template v-else-if="kind==='asset-detail'"><div v-if="d.type==='提示词'" class="asset-detail-prompt">{{d.text}}</div><ProductScene v-else :variant="d.scene"/><h3>{{d.name}}</h3><div class="asset-tags"><span>{{d.category}}</span><span v-for="t in d.tags" :key="t">{{t}}</span></div></template><template v-else-if="kind==='row-reference'"><span class="eyebrow">镜头 {{p.row(d.node.rowId)?.number}} · {{s.projectName}}</span><h3>正在引用这一行的内容</h3><p class="reference-full-text">{{p.referenceText(d.node)}}</p><p class="help-copy">内容作为来源参考，不会覆盖节点中的手写输入。生成时固定当前版本。</p></template><template v-else-if="kind==='optimize'"><label>风格要求</label><textarea v-model="input" rows="4" placeholder="希望更自然、更有电影感，或调整光线与构图…"></textarea><p class="help-copy">预览追加内容：{{input||'填写风格要求后在此预览'}}</p></template><template v-else-if="kind==='tasks'"><div v-if="!s.tasks.length" class="empty-panel"><Icon name="clock" :size="30"/><h3>还没有生成任务</h3><p>节点发起生成后，会在这里显示进度。</p></div><div v-for="t in s.tasks" :key="t.id" class="task-row"><Icon name="image"/><span>{{t.name}}</span><span>{{t.status}}</span></div></template><template v-else-if="kind==='question'"><p>你希望镜头采用哪种视觉风格？</p><div class="style-options"><button v-for="t in ['自然通透','电影质感','极简产品摄影']" :key="t" :class="{selected:input===t}" @click="input=t"><Icon name="spark"/>{{t}}</button></div><p class="help-copy">未选择或关闭面板不视为确认。</p></template><template v-else-if="kind==='feedback'"><label>确认对象版本</label><input v-model="feedback.version"/><label>线下确认结果</label><select v-model="feedback.status"><option>待确认</option><option>需修改</option><option>已确认</option></select><label>修改意见</label><textarea v-model="feedback.opinion" rows="5" placeholder="记录需求方在线下提出的修改意见…"></textarea><p class="help-copy">记录不会自动发起返工生成，新版本不继承旧确认结果。</p></template><template v-else-if="kind==='export'"><p class="help-copy">导出内容预览。当前原型不生成真实 PDF／Excel 文件。</p><div v-if="d.kind==='excel'" class="table-editor-scroll"><table class="script-table"><thead><tr><th v-for="c in s.columns" :key="c">{{c}}</th></tr></thead><tbody><tr v-for="row in s.rows" :key="row.id"><td v-for="key in keys" :key="key">{{row[key]}}</td></tr></tbody></table></div><div v-else class="document-preview"><h2>{{s.projectName}}</h2><p>{{text||'创作目标与风格正文'}}</p></div></template><template v-else-if="kind==='projects'"><button v-for="name in ['夏日序曲 · 香水新品宣传','品牌开放日 · 活动预热']" :key="name" class="project-list-item" @click="p.openProject(name);p.closeModal()"><Icon name="folder"/>{{name}}<Icon name="arrow"/></button></template><template v-else-if="kind==='media-preview'"><ProductScene :variant="d.scene"/><p class="help-copy">视频播放效果示意，真实预览将在接入生成服务后提供。</p></template><template v-else><div class="guide-steps"><div v-for="(t,i) in ['描述目标，引用参考内容','生成完整分镜表，编辑每个镜头','将分镜行连接图片或视频节点','确认生成范围，下载采用素材','在外部软件剪辑并记录反馈']" :key="t"><span>{{i+1}}</span>{{t}}</div></div></template></div><footer class="modal-footer"><span v-if="kind==='save'" class="footer-note"><Icon name="folder" :size="13"/>仅自己可见</span><span v-else class="footer-note"></span><button class="secondary-button" @click="close()">{{['guide','tasks','row-reference','media-preview','asset-detail','projects','export'].includes(kind)?'关闭':'取消'}}</button><button v-if="kind==='save'" class="primary-button" @click="p.saveAsset(form)"><Icon name="save" :size="15"/>保存资产</button><button v-else-if="kind==='script-input'" class="primary-button" @click="p.generateScript()"><Icon name="spark" :size="15"/>生成分镜</button><button v-else-if="kind==='text-editor'" class="primary-button" @click="saveText()">确定</button><button v-else-if="kind==='script-editor'" class="primary-button" @click="p.closeModal()">完成编辑</button><button v-else-if="kind==='confirm'" class="primary-button" @click="p.confirm()">确认</button><button v-else-if="kind==='delete-session'" class="primary-button danger" @click="p.deleteSession()">确认删除</button><button v-else-if="kind==='apply'" class="primary-button" :disabled="!applyNode" @click="p.applyAsset(d,applyNode)">引用</button><button v-else-if="kind==='download'" class="primary-button" :disabled="s.busy||(!onlyAvailable&&outputRows.some(r=>!outputs.some(n=>n.rowId===r.id)))||!outputs.length" @click="p.prepareDownload()">{{s.busy?'正在准备…':'准备下载'}}</button><button v-else-if="kind==='rename-project'||kind==='new-project'" class="primary-button" :disabled="!input.trim()" @click="kind==='new-project'?p.newProject(input):s.projectName=input;p.closeModal()">确定</button><button v-else-if="kind==='rename-session'" class="primary-button" :disabled="!input.trim()" @click="p.renameSession(input);p.closeModal()">确定</button><button v-else-if="kind==='question'" class="primary-button" :disabled="!input" @click="s.messages.push({role:'user',text:'视觉风格：'+input});p.closeModal()">提交选择</button><button v-else-if="kind==='feedback'" class="primary-button" @click="p.notify('已记录线下确认意见（交互预览）');p.closeModal()">保存记录</button><button v-else-if="kind==='optimize'" class="primary-button" @click="p.setNode(d.node.id,'prompt',(d.node.prompt||p.referenceText(d.node))+'，'+input);p.notify('已应用优化内容，可继续编辑');p.closeModal()">预览并应用</button></footer></section></div></template>
